  "test": "import importlib
import os


def test_observe_sampling(monkeypatch):
    # Ensure sampling rate 0 disables tracing
    monkeypatch.setenv('OBSERVABILITY_SAMPLE_RATE', '0')
    obs_mod = importlib.reload(importlib.import_module('browser_use.observability'))

    # Provide a dummy lmnr.observe implementation
    def dummy_observe(**kwargs):
        def decorator(func):
            setattr(func, '_observed', True)
            return func
        return decorator

    obs_mod._LMNR_AVAILABLE = True
    obs_mod._lmnr_observe = dummy_observe

    @obs_mod.observe(name='test')
    def foo():
        return 1

    assert not hasattr(foo, '_observed')

    # Now set sampling rate to 1 to enable tracing
    monkeypatch.setenv('OBSERVABILITY_SAMPLE_RATE', '1')
    obs_mod = importlib.reload(importlib.import_module('browser_use.observability'))
    obs_mod._LMNR_AVAILABLE = True
    obs_mod._lmnr_observe = dummy_observe

    @obs_mod.observe(name='test')
    def bar():
        return 2

    assert getattr(bar, '_observed', False) is True"
